    """Extend r+c=constant diagonal"""
    seen = set()
    sr, sc = r, c
    for i in range(H + W, 0, -1):
        sr, sc = r + (i-1) if (i-1) >= 0 else r + min(i-1, 14), c - (i-1) if i-1 > 0 else c
