def extend_all_diags(grid, r, c, v, H, W):
    """Extend a single pixel value in ALL 4 diagonal directions"""
    s = r + c  # r+c constant diagonal
    # r+c diagonal: row increases, col decreases
    i = 1
    while True:
        nr, nc = r + i, c - i
        if not (0 <= nr < H and 0 <= nc < W):
            break
        if grid[nr][nc] == 9:
            grid[nr][nc] = v
        elif grid[nr][nc] != v:
            break
        i += 1

    # r+c diagonal: row decreases, col increases
    i = 1
    while True:
        nr, nc = r - i, c + i
        if not (0 <= nr < H and 0 <= nc < W):
            break
        if grid[nr][nc] == 9:
            grid[nr][nc] = v
        elif grid[nr][nc] != v:
            break
        i += 1

    # r-c diagonal: col increases, row increases
    for nc in range(c + 1, W):
        nr = r + (nc - c)
        if not (0 <= nr < H):
            continue
        if grid[nr][nc] == 9:
            grid[nr][nc] = v
        elif grid[nr][nc] != v:
            break

    # r-c diagonal: col decreases, row decreases
    for nc in range(c - 1, -1, -1):
        nr = r - (c - nc)
        if not (0 <= nr < H):
            continue
        if grid[nr][nc] == 9:
            grid[nr][nc] = v
        elif grid[nr][nc] != v:
            break

